//! Golden-fixture parity with the Python reference implementation.
//!
//! `fixtures/golden/*.json` is generated by `scripts/gen_fixtures.py` from a
//! pinned checkout of NovelAI-Image-MCP. These tests assert the port is
//! **byte-identical** on the wire and text-identical in error messages, so a
//! transcription slip fails CI instead of silently changing behavior.

use novelai_image_sdk::auth::derive_access_key;
use novelai_image_sdk::constants::{
    Action, ControlNetModel, DirectorTool, Emotion, EmotionLevel, Model, NoiseSchedule, Sampler,
    UPSCALE_MODELS, quality_tags, uc_presets,
};
use novelai_image_sdk::error::{ErrorCode, parse_error_body};
use novelai_image_sdk::models::{CharacterPrompt, GenerationRequest};
use novelai_image_sdk::payload::build_generation_payload;
use novelai_image_sdk::response::check_status;
use serde::Deserialize;
use serde_json::{Value, json};

fn fixture(name: &str) -> Value {
    let path = format!(
        "{}/../../fixtures/golden/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("read {path}: {e} — run scripts/gen_fixtures.py"));
    serde_json::from_str(&text).expect("fixture is valid JSON")
}

#[test]
fn constants_match_reference() {
    let expected = fixture("constants.json");

    let models: Vec<Value> = expected["models"].as_array().unwrap().clone();
    assert_eq!(models.len(), Model::ALL.len(), "model count");
    for entry in &models {
        let id = entry["id"].as_str().unwrap();
        let model: Model = id.parse().expect("known model");
        assert_eq!(entry["is_v4"], model.is_v4(), "{id} is_v4");
        assert_eq!(entry["is_v5"], model.is_v5(), "{id} is_v5");
        assert_eq!(entry["inpaint"], model.is_inpaint(), "{id} inpaint");
        assert_eq!(entry["vibe"], model.supports_vibe(), "{id} vibe");
        assert_eq!(entry["upscale"], model.supports_upscale(), "{id} upscale");
        assert_eq!(
            entry["params_version"].as_u64().unwrap(),
            u64::from(model.params_version()),
            "{id} params_version"
        );
        assert_eq!(entry["quality"], quality_tags(model), "{id} quality tags");
        let presets: Vec<String> = entry["uc_presets"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_owned())
            .collect();
        assert_eq!(
            presets,
            uc_presets(model).map(str::to_owned).to_vec(),
            "{id} uc presets"
        );
    }

    let wire = |key: &str, values: &[&str]| {
        let expected: Vec<&str> = expected[key]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        assert_eq!(expected, values, "{key}");
    };
    wire(
        "samplers",
        &Sampler::ALL.iter().map(|s| s.as_wire()).collect::<Vec<_>>(),
    );
    wire(
        "noise_schedules",
        &NoiseSchedule::ALL
            .iter()
            .map(|s| s.as_wire())
            .collect::<Vec<_>>(),
    );
    wire(
        "actions",
        &Action::ALL.iter().map(|s| s.as_wire()).collect::<Vec<_>>(),
    );
    wire(
        "controlnet_models",
        &ControlNetModel::ALL
            .iter()
            .map(|s| s.as_wire())
            .collect::<Vec<_>>(),
    );
    wire(
        "director_tools",
        &DirectorTool::ALL
            .iter()
            .map(|s| s.as_wire())
            .collect::<Vec<_>>(),
    );
    wire(
        "emotions",
        &Emotion::ALL.iter().map(|s| s.as_wire()).collect::<Vec<_>>(),
    );

    let levels: Vec<Vec<Value>> = expected["emotion_levels"]
        .as_array()
        .unwrap()
        .iter()
        .map(|pair| pair.as_array().unwrap().clone())
        .collect();
    assert_eq!(levels.len(), 6);
    for (index, pair) in levels.iter().enumerate() {
        let level = EmotionLevel::try_from(index as u8).expect("level");
        assert_eq!(pair[1].as_u64().unwrap(), u64::from(level.as_u8()));
    }

    let upscale: Vec<&str> = expected["upscale_models"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap())
        .collect();
    let ours: Vec<&str> = UPSCALE_MODELS.iter().map(|m| m.as_wire()).collect();
    let mut ours_sorted = ours.clone();
    ours_sorted.sort_unstable();
    assert_eq!(upscale, ours_sorted);
}

#[test]
fn access_key_matches_reference() {
    let expected = fixture("access_key.json");
    for case in expected.as_array().unwrap() {
        let username = case["username"].as_str().unwrap();
        let password = case["password"].as_str().unwrap();
        let key = case["key"].as_str().unwrap();
        assert_eq!(derive_access_key(username, password).unwrap(), key);
    }
}

#[derive(Debug, Deserialize)]
struct RequestSpec {
    prompt: String,
    model: String,
    action: String,
    negative_prompt: String,
    width: u32,
    height: u32,
    n_samples: u32,
    steps: u32,
    scale: f64,
    sampler: String,
    seed: u32,
    noise_schedule: String,
    quality: bool,
    uc_preset: u8,
    references: Vec<String>,
    character_prompts: Vec<Value>,
    image: Option<String>,
    mask: Option<String>,
    strength: Option<f64>,
    noise: Option<f64>,
    smea: Option<bool>,
    smea_dynamic: Option<bool>,
    auto_smea: bool,
    straight_alpha: bool,
}

fn build(spec: &RequestSpec) -> GenerationRequest {
    let mut builder = GenerationRequest::new(spec.prompt.clone())
        .model(spec.model.parse().unwrap())
        .action(spec.action.parse().unwrap())
        .negative_prompt(spec.negative_prompt.clone())
        .width(spec.width)
        .height(spec.height)
        .n_samples(spec.n_samples)
        .steps(spec.steps)
        .scale(spec.scale)
        .sampler(spec.sampler.parse().unwrap())
        .seed(spec.seed)
        .noise_schedule(spec.noise_schedule.parse().unwrap())
        .quality(spec.quality)
        .uc_preset(spec.uc_preset)
        .straight_alpha(spec.straight_alpha)
        .auto_smea(spec.auto_smea)
        .smea(spec.smea)
        .smea_dynamic(spec.smea_dynamic)
        .image(spec.image.clone())
        .mask(spec.mask.clone())
        .strength(spec.strength)
        .noise(spec.noise);
    if !spec.character_prompts.is_empty() {
        let characters: Vec<CharacterPrompt> = spec
            .character_prompts
            .iter()
            .map(|value| CharacterPrompt {
                prompt: value["prompt"].as_str().unwrap().to_owned(),
                negative_prompt: value["negative_prompt"].as_str().unwrap().to_owned(),
                x: value["x"].as_f64().unwrap(),
                y: value["y"].as_f64().unwrap(),
                enabled: value["enabled"].as_bool().unwrap(),
            })
            .collect();
        builder = builder.character_prompts(characters);
    }
    // `extra_noise_seed` is random in production; fixtures pass a fixed value
    // only for img2img/inpaint, so replay it.
    if spec.strength.is_some() || spec.noise.is_some() || !spec.references.is_empty() {
        builder = builder.extra_noise_seed(Some(0));
    }
    let _ = &spec.references;
    builder.build().expect("fixture request is valid")
}

#[test]
fn payload_wire_bytes_match_reference() {
    let expected = fixture("payloads.json");
    let cases = expected.as_array().unwrap();
    assert!(!cases.is_empty());
    for (index, case) in cases.iter().enumerate() {
        let spec: RequestSpec = serde_json::from_value(case["request"].clone()).unwrap();
        let request = build(&spec);
        let payload = build_generation_payload(&request);
        let wire = serde_json::to_string(&payload).unwrap();

        // The fixture's `wire` may contain a random extra_noise_seed for
        // image-conditioned requests; compare structurally in that case.
        let expected_wire: Value =
            serde_json::from_str(case["wire"].as_str().unwrap()).expect("fixture wire is JSON");
        let mut ours = payload.clone();
        let mut theirs = expected_wire;
        if spec.strength.is_some() {
            ours["parameters"]["extra_noise_seed"] = json!(0);
            theirs["parameters"]["extra_noise_seed"] = json!(0);
        }
        assert_eq!(
            ours, theirs,
            "payload #{index} (model {}) differs",
            spec.model
        );

        // Key order must also match: serde_json preserves insertion order.
        let expected_keys: Vec<&str> = case["keys"]["top"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        let actual = wire.as_str();
        let mut cursor = 0;
        for key in &expected_keys {
            let needle = format!("\"{key}\":");
            let found = actual[cursor..]
                .find(&needle)
                .unwrap_or_else(|| panic!("payload #{index}: missing key {key} in {actual}"));
            cursor += found + needle.len();
        }

        let expected_params: Vec<&str> = case["keys"]["parameters"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap())
            .collect();
        let actual_params = payload["parameters"].as_object().unwrap();
        for key in &expected_params {
            assert!(
                actual_params.contains_key(*key),
                "payload #{index}: parameters missing {key}"
            );
        }
    }
}

#[test]
fn anlas_estimates_match_reference() {
    let cases = fixture("anlas.json");
    for case in cases.as_array().unwrap() {
        let action: Action = case["action"].as_str().unwrap().parse().unwrap();
        let mut builder = GenerationRequest::new("x")
            .width(case["width"].as_u64().unwrap() as u32)
            .height(case["height"].as_u64().unwrap() as u32)
            .steps(case["steps"].as_u64().unwrap() as u32)
            .n_samples(case["n_samples"].as_u64().unwrap() as u32)
            .model(case["model"].as_str().unwrap().parse().unwrap())
            .action(action)
            .auto_smea(case["auto_smea"].as_bool().unwrap());
        if let Some(strength) = case["strength"].as_f64() {
            builder = builder
                .strength(Some(strength))
                .image(Some("aGVsbG8=".into()));
        }
        if let Some(value) = case["smea"].as_bool() {
            builder = builder.smea(Some(value));
        }
        if let Some(value) = case["smea_dynamic"].as_bool() {
            builder = builder.smea_dynamic(Some(value));
        }
        let request = builder.build().expect("fixture request is valid");
        let expected = case["opus"].as_u64().unwrap() as u32;
        let expected_free = case["opus_free"].as_u64().unwrap() as u32;
        assert_eq!(
            request.estimate_anlas_cost(false),
            expected,
            "{}x{} steps {} samples {}",
            request.width,
            request.height,
            request.steps,
            request.n_samples
        );
        assert_eq!(
            request.estimate_anlas_cost(true),
            expected_free,
            "opus-free {}x{} steps {}",
            request.width,
            request.height,
            request.steps
        );
    }
}

#[test]
fn error_messages_match_reference() {
    let cases = fixture("errors.json");
    for case in cases.as_array().unwrap() {
        let status = case["status"].as_u64().unwrap() as u16;
        let body = case["body"].as_str().unwrap();

        let info = parse_error_body(body.as_bytes());
        let expected_code = match &case["parsed"]["code"] {
            Value::Number(n) => Some(ErrorCode::Http(n.as_u64().unwrap() as u16)),
            Value::String(s) => Some(ErrorCode::Api(s.clone())),
            _ => None,
        };
        assert_eq!(info.code, expected_code, "code for {body}");
        assert_eq!(
            info.message,
            case["parsed"]["message"].as_str().unwrap(),
            "message for {body}"
        );

        let ours = check_status(status, body.as_bytes());
        match &case["raised"] {
            Value::Object(raised) => {
                let err = ours.expect_err("reference raised");
                assert_eq!(err.to_string(), raised["message"].as_str().unwrap());
                let code = match &raised["code"] {
                    Value::Number(n) => ErrorCode::Http(n.as_u64().unwrap() as u16),
                    Value::String(s) => ErrorCode::Api(s.clone()),
                    _ => panic!("unexpected code"),
                };
                assert_eq!(err.code(), Some(&code));
                let expected_explanation = raised["explanation"].as_str();
                assert_eq!(err.explanation(), expected_explanation);
            }
            _ => assert!(ours.is_ok(), "reference did not raise for {body}"),
        }
    }
}
